Contract ManageItemCRUDService::createItem(barcode:Integer,name:String,price:Real,stocknumber:Integer,orderprice:Real): Boolean {
          definition:
          theItem:Item = Item.allInstance()->any(i|i.Barcode=barcode)


            postcondition:
          theItem.oclIsUndefined()=false and result=true or let newItem:Item in newItem.oclIsNew() and newItem.Barcode=barcode and newItem.Name=name and newItem.Price=price and newItem.StockNumber=stocknumber and newItem.OrderPrice=orderprice and Item.allInstance()->includes(newItem) and result=true

        }
